	private static boolean validRevision(String revision) {
		return revision != null && revision.matches("[0-9a-f]{40}");
	}

	static String canonicalTerm(Value value) {
		return JSON.writeValueAsString(encodeTerm(value));
	}

	private static Object encodeTerm(Value value) {
		if (value instanceof IRI iri) {
			return List.of("iri", iri.stringValue());
		}
		if (value instanceof BNode blank) {
			return List.of("bnode", blank.getID());
		}
		if (value instanceof Literal literal) {
			return List.of("literal", literal.getLabel(), literal.getDatatype().stringValue(),
					literal.getLanguage().orElse(""), literal.getBaseDirection().name());
		}
		if (value instanceof TripleTerm triple) {
			return List.of("triple", encodeTerm(triple.getSubject()), encodeTerm(triple.getPredicate()),
					encodeTerm(triple.getObject()));
		}
		throw new IllegalArgumentException("Unsupported RDF term " + value);
	}

	private static Value decodeTerm(JsonNode term) {
		if (!term.isArray() || term.isEmpty()) {
			throw new IllegalArgumentException("invalid RDF term");
		}
		String type = text(term.get(0));
		return switch (type) {
		case "iri" -> {
			requireSize(term, 2);
			yield VF.createIRI(text(term.get(1)));
		}
		case "bnode" -> {
			requireSize(term, 2);
			yield VF.createBNode(text(term.get(1)));
		}
		case "literal" -> {
			requireSize(term, 5);
			String label = text(term.get(1));
			IRI datatype = VF.createIRI(text(term.get(2)));
			String language = text(term.get(3));
			Literal.BaseDirection direction = Literal.BaseDirection.valueOf(text(term.get(4)));
			if (language.isEmpty() && direction != Literal.BaseDirection.NONE) {
				throw new IllegalArgumentException("direction without language in literal term");
			}
			Literal literal = language.isEmpty() ? VF.createLiteral(label, datatype)
					: VF.createLiteral(label, language, direction);
			if (!literal.getDatatype().equals(datatype)) {
				throw new IllegalArgumentException("inconsistent datatype in language literal term");
			}
			yield literal;
		}
		case "triple" -> {
			requireSize(term, 4);
			yield VF.createTripleTerm((Resource) decodeTerm(term.get(1)), (IRI) decodeTerm(term.get(2)),
					decodeTerm(term.get(3)));
		}
		default -> throw new IllegalArgumentException("unsupported RDF term type " + type);
		};
	}

	private static String text(JsonNode node) {
		if (node == null || !node.isTextual()) {
			throw new IllegalArgumentException("RDF term component must be text");
		}
		return node.asText();
	}

	private static void requireSize(JsonNode node, int size) {
		if (node.size() != size) {
			throw new IllegalArgumentException("invalid RDF term arity");
		}
	}

	private static String sha256(String value) {
		try {
			return HexFormat.of()
					.formatHex(MessageDigest.getInstance("SHA-256")
							.digest(value.getBytes(StandardCharsets.UTF_8)));
		} catch (NoSuchAlgorithmException impossible) {
			throw new IllegalStateException("SHA-256 unavailable", impossible);
		}
	}
